design\releases\0_2_0\card__1ebcfe45-9445-47e6-8619-6c72708bd91b.json:200:          "content": "import { Box, Typography } from '@mui/material'\nimport {\n    useEffect, useRef, useState, useSyncExternalStore, type KeyboardEvent, type PointerEvent as ReactPointerEvent, type ReactNode,\n} from 'react'\nimport { ACTION_PROMPT_PLACEHOLDERS } from '../../../data/action_placeholders'\nimport { dialogService } from '../../../services/dialog_service'\nimport type { ActionPromptDraft } from '../../../services/actions/action_prompt_draft_service'\nimport { MarkdownEditor, type MarkdownEditorHandle } from '../../editor/markdown_editor'\n\nconst MIN_PROMPT_HEIGHT = 72\nconst MIN_CHAT_HEIGHT = 96\nconst DEFAULT_PROMPT_HEIGHT = 140\nconst PROMPT_RESIZE_STEP = 24\nconst PROMPT_HEIGHT_STORAGE_KEY = 'md2.actionPromptHeight'\n\nfunction readStoredPromptHeight(): number {\n    const storedValue = window.localStorage.getItem(PROMPT_HEIGHT_STORAGE_KEY)\n    const parsedValue = storedValue ? Number.parseInt(storedValue, 10) : Number.NaN\n\n    return Number.isNaN(parsedValue) ? DEFAULT_PROMPT_HEIGHT : parsedValue\n}\n\ninterface ActionAgentPromptProps {\n    convertMessage: string | null\n    disabled: boolean\n    onRunShortcut?: () => void\n    promptDraft: ActionPromptDraft\n    responsePrompts?: ReactNode\n}\n\n/** Resizable prompt editor shown below an agent conversation. */\nexport function ActionAgentPrompt(props: ActionAgentPromptProps) {\n    const {convertMessage, disabled, onRunShortcut, promptDraft, responsePrompts} = props\n    const promptEditorRef = useRef<MarkdownEditorHandle>(null)\n    const promptHeightStartRef = useRef(0)\n    const pointerStartYRef = useRef(0)\n    const splitContainerRef = useRef<HTMLElement | null>(null)\n    const [promptHeight, setPromptHeight] = useState(readStoredPromptHeight)\n    const [resizingPrompt, setResizingPrompt] = useState(false)\n    const editorSnapshot = useSyncExternalStore(\n        promptDraft.subscribeEditor,\n        promptDraft.getEditorSnapshot,\n        promptDraft.getEditorSnapshot,\n    )\n\n    useEffect(() => {\n        promptEditorRef.current?.setMarkdown(promptDraft.getSnapshot())\n    }, [editorSnapshot.replacementRevision, promptDraft])\n\n    const handlePromptChange = (value: string) => {\n        promptDraft.edit(value)\n        void promptDraft.synchronize().catch((error: unknown) => {\n            dialogService.error(error, { fallbackMessage: 'Could not queue agent prompt' })\n        })\n    }\n\n    const clampPromptHeight = (proposed: number) => {\n        const container = splitContainerRef.current\n        const available = container ? container.getBoundingClientRect().height - MIN_CHAT_HEIGHT : proposed\n        const max = Math.max(MIN_PROMPT_HEIGHT, available)\n\n        return Math.min(Math.max(proposed, MIN_PROMPT_HEIGHT), max)\n    }\n\n    const persistPromptHeight = (height: number) => {\n        window.localStorage.setItem(PROMPT_HEIGHT_STORAGE_KEY, String(Math.round(height)))\n    }\n\n    const handleSplitPointerDown = (event: ReactPointerEvent<HTMLDivElement>) => {\n        event.preventDefault()\n        splitContainerRef.current = event.currentTarget.parentElement\n        promptHeightStartRef.current = promptHeight\n        pointerStartYRef.current = event.clientY\n        setResizingPrompt(true)\n        event.currentTarget.setPointerCapture?.(event.pointerId)\n    }\n\n    const handleSplitPointerMove = (event: ReactPointerEvent<HTMLDivElement>) => {\n        if (!resizingPrompt) return\n\n        const delta = pointerStartYRef.current - event.clientY\n        setPromptHeight(clampPromptHeight(promptHeightStartRef.current + delta))\n    }\n\n    const handleSplitPointerUp = (event: ReactPointerEvent<HTMLDivElement>) => {\n        if (!resizingPrompt) return\n\n        setResizingPrompt(false)\n        event.currentTarget.releasePointerCapture?.(event.pointerId)\n        setPromptHeight((height) => {\n            persistPromptHeight(height)\n\n            return height\n        })\n    }\n\n    const handleSplitKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {\n        splitContainerRef.current = event.currentTarget.parentElement\n        const nextByKey: Record<string, number> = {\n            ArrowDown: promptHeight - PROMPT_RESIZE_STEP,\n            ArrowUp: promptHeight + PROMPT_RESIZE_STEP,\n        }\n        const next = nextByKey[event.key]\n        if (next === undefined) return\n\n        event.preventDefault()\n        const clamped = clampPromptHeight(next)\n        setPromptHeight(clamped)\n        persistPromptHeight(clamped)\n    }\n\n    const handlePromptKeyDownCapture = (event: KeyboardEvent<HTMLDivElement>) => {\n        if (event.key !== 'Enter' || (!event.ctrlKey && !event.metaKey) || !onRunShortcut) return\n\n        event.preventDefault()\n        event.stopPropagation()\n        promptEditorRef.current?.flush()\n        onRunShortcut()\n    }\n\n    return (\n        <>\n            <Box\n                aria-label=\"Resize prompt\"\n                aria-orientation=\"horizontal\"\n                aria-valuemin={MIN_PROMPT_HEIGHT}\n                aria-valuenow={Math.round(promptHeight)}\n                onKeyDown={handleSplitKeyDown}\n                onPointerDown={handleSplitPointerDown}\n                onPointerMove={handleSplitPointerMove}\n                onPointerUp={handleSplitPointerUp}\n                role=\"separator\"\n                sx={{\n                    bgcolor: resizingPrompt ? 'primary.main' : 'divider',\n                    borderRadius: '2px',\n                    cursor: 'row-resize',\n                    flexShrink: 0,\n                    height: '3px',\n                    mx: 'auto',\n                    my: '2px',\n                    width: '100%',\n                    '&:hover': { bgcolor: 'primary.main' },\n                }}\n                tabIndex={0}\n            />\n            <Box\n                aria-label=\"Prompt\"\n                onKeyDownCapture={handlePromptKeyDownCapture}\n                sx={{\n                    borderRadius: '9px',\n                    border: 1,\n                    borderColor: 'custom.borderStrong',\n                    display: 'flex',\n                    flexDirection: 'column',\n                    flexShrink: 0,\n                    height: promptHeight,\n                    overflow: 'hidden',\n                    '&:focus-within': {\n                        borderColor: 'primary.main',\n                        boxShadow: (theme) => `0 0 0 3px ${theme.palette.action.selected}`,\n                    },\n                }}\n            >\n                <Box sx={{ flex: 1, minHeight: 0, overflowY: 'auto', px: 1 }}>\n                    <MarkdownEditor\n                        flushOnBlur\n                        hideToolbar\n                        markdown={promptDraft.getSnapshot()}\n                        onChange={handlePromptChange}\n                        onLiveChange={promptDraft.edit}\n                        placeholders={ACTION_PROMPT_PLACEHOLDERS}\n                        readOnly={disabled || editorSnapshot.preparationStatus !== 'ready'}\n                        ref={promptEditorRef}\n                    />\n                </Box>\n                {responsePrompts}\n            </Box>\n            {convertMessage ? (\n                <Typography color=\"text.secondary\" role=\"status\" variant=\"caption\">\n                    {convertMessage}\n                </Typography>\n            ) : null}\n        </>\n    )\n}\n\r\nimport { act, cleanup, fireEvent, render, screen } from '@testing-library/react'\nimport { afterEach, describe, expect, it, vi } from 'vitest'\nimport { ActionAgentPrompt } from './action_agent_prompt'\nimport { ACTION_PROMPT_PLACEHOLDERS } from '../../../data/action_placeholders'\nimport { ActionPromptDraft } from '../../../services/actions/action_prompt_draft_service'\n\nconst setMarkdown = vi.hoisted(() => vi.fn())\n\nvi.mock('../../editor/markdown_editor', async () => {\n    const { forwardRef, useImperativeHandle, useRef, useState } = await import('react')\n\n    return {\n        MarkdownEditor: forwardRef(function MarkdownEditorMock(props: {\n            flushOnBlur?: boolean\n            markdown: string\n            onChange: (markdown: string) => void\n            onLiveChange?: (markdown: string) => void\n            placeholders?: readonly { name: string }[]\n            readOnly?: boolean\n        }, ref) {\n            const valueRef = useRef(props.markdown)\n            const [value, setValue] = useState(props.markdown)\n            useImperativeHandle(ref, () => ({\n                flush: () => {\n                    props.onChange(valueRef.current)\n\n                    return true\n                },\n                getMarkdown: () => valueRef.current,\n                setMarkdown: (markdown: string) => {\n                    valueRef.current = markdown\n                    setValue(markdown)\n                    setMarkdown(markdown)\n                },\n            }))\n\n            return (\n                <textarea\n                    aria-label=\"Markdown prompt\"\n                    data-flush-on-blur={props.flushOnBlur ? 'true' : 'false'}\n                    data-placeholders={props.placeholders?.map(({ name }) => name).join(',')}\n                    value={value}\n                    onBlur={(event) => props.onChange(event.currentTarget.value)}\n                    onChange={(event) => {\n                        valueRef.current = event.currentTarget.value\n                        setValue(event.currentTarget.value)\n                        props.onLiveChange?.(event.currentTarget.value)\n                    }}\n                    onKeyDown={(event) => {\n                        if (event.key !== 'Enter') return\n\n                        const nextValue = `${valueRef.current}\\n`\n                        valueRef.current = nextValue\n                        setValue(nextValue)\n                        props.onLiveChange?.(nextValue)\n                    }}\n                    readOnly={props.readOnly}\n                />\n            )\n        }),\n    }\n})\n\nafterEach(cleanup)\n\ndescribe('ActionAgentPrompt', () => {\n    it('configures action placeholders on its hidden-toolbar editor', () => {\n        const promptDraft = new ActionPromptDraft('', false, null)\n        render(\n            <ActionAgentPrompt\n                convertMessage={null}\n                disabled={false}\n                promptDraft={promptDraft}\n            />,\n        )\n\n        expect(screen.getByLabelText('Markdown prompt')).toHaveAttribute(\n            'data-placeholders',\n            ACTION_PROMPT_PLACEHOLDERS.map(({ name }) => name).join(','),\n        )\n        expect(screen.getByLabelText('Markdown prompt').getAttribute('data-placeholders')).toContain('this-card')\n    })\n\n    it('keeps typing local and synchronizes the prompt on blur', () => {\n        const promptDraft = new ActionPromptDraft('', false, null)\n        const synchronize = vi.spyOn(promptDraft, 'synchronize')\n        render(\n            <ActionAgentPrompt\n                convertMessage={null}\n                disabled={false}\n                promptDraft={promptDraft}\n            />,\n        )\n        const prompt = screen.getByLabelText('Markdown prompt')\n\n        fireEvent.change(prompt, { target: { value: 'Draft' } })\n\n        expect(synchronize).not.toHaveBeenCalled()\n        expect(promptDraft.getSnapshot()).toBe('Draft')\n        expect(prompt).toHaveAttribute('data-flush-on-blur', 'true')\n\n        fireEvent.blur(prompt)\n\n        expect(synchronize).toHaveBeenCalledOnce()\n    })\n\n    it.each([\n        { keyModifier: { ctrlKey: true }, shortcut: 'Ctrl+Enter' },\n        { keyModifier: { metaKey: true }, shortcut: 'Meta+Enter' },\n    ])('flushes the latest prompt before running $shortcut without passing it to the editor', ({ keyModifier }) => {\n        const handleRunShortcut = vi.fn()\n        const promptDraft = new ActionPromptDraft('', false, null)\n        const synchronize = vi.spyOn(promptDraft, 'synchronize')\n        render(\n            <ActionAgentPrompt\n                convertMessage={null}\n                disabled={false}\n                onRunShortcut={handleRunShortcut}\n                promptDraft={promptDraft}\n            />,\n        )\n        const prompt = screen.getByLabelText('Markdown prompt')\n\n        fireEvent.change(prompt, { target: { value: 'Run this' } })\n        fireEvent.keyDown(prompt, { ...keyModifier, key: 'Enter' })\n\n        expect(synchronize).toHaveBeenCalledOnce()\n        expect(synchronize.mock.invocationCallOrder[0]).toBeLessThan(handleRunShortcut.mock.invocationCallOrder[0])\n        expect(handleRunShortcut).toHaveBeenCalledOnce()\n        expect(promptDraft.getSnapshot()).toBe('Run this')\n        expect(prompt).toHaveValue('Run this')\n    })\n\n    it('keeps plain Enter and Shift+Enter editor behavior', () => {\n        const promptDraft = new ActionPromptDraft('Line', false, null)\n        render(\n            <ActionAgentPrompt\n                convertMessage={null}\n                disabled={false}\n                onRunShortcut={vi.fn()}\n                promptDraft={promptDraft}\n            />,\n        )\n        const prompt = screen.getByLabelText('Markdown prompt')\n\n        fireEvent.keyDown(prompt, { key: 'Enter' })\n        fireEvent.keyDown(prompt, { key: 'Enter', shiftKey: true })\n\n        expect(promptDraft.getSnapshot()).toBe('Line\\n\\n')\n        expect(prompt).toHaveValue('Line\\n\\n')\n    })\n\n    it('keeps Ctrl+Enter editor behavior when no shortcut callback exists', () => {\n        const promptDraft = new ActionPromptDraft('Line', false, null)\n        render(\n            <ActionAgentPrompt\n                convertMessage={null}\n                disabled={false}\n                promptDraft={promptDraft}\n            />,\n        )\n        const prompt = screen.getByLabelText('Markdown prompt')\n\n        fireEvent.keyDown(prompt, { ctrlKey: true, key: 'Enter' })\n\n        expect(promptDraft.getSnapshot()).toBe('Line\\n')\n        expect(prompt).toHaveValue('Line\\n')\n    })\n\n    it('applies each external replacement to the mounted editor once', () => {\n        const promptDraft = new ActionPromptDraft('Initial', false, null)\n        render(\n            <ActionAgentPrompt\n                convertMessage={null}\n                disabled={false}\n                promptDraft={promptDraft}\n            />,\n        )\n        setMarkdown.mockClear()\n\n        act(() => promptDraft.replace('Prepared'))\n\n        expect(setMarkdown).toHaveBeenCalledOnce()\n        expect(setMarkdown).toHaveBeenCalledWith('Prepared')\n        expect(screen.getByLabelText('Markdown prompt')).toHaveValue('Prepared')\n    })\n})\n\r\n---\ninternalId: f2ec9e28-8064-4707-bce9-b62f24d57524\n---\n\n# App Style Guide â€” Kanban / MDÂ² (React + MUI)\n\nHow to build **any new component** so it matches the app. This is written for **Material UI v5+** components.\n\n**The theme is the source of truth.** All color, radius, base typography, and spacing units live in the single `createTheme` (defined in `GUIDANCE.md` Â§1/Â§9). This guide does **not** define colors â€” it tells you **which theme value to use for which role**, and covers the things the theme can't encode: layout, spacing/margins, borders, elevation, and component conventions.\n\n**The one rule that matters:** never write a raw hex, px radius, or magic color into a component. Read it from the theme (`theme.palette.*`, `theme.shape`, `theme.typography`, `theme.spacing`). If a component has a hardcoded hex in its `sx`/styled, it's wrong â€” that's exactly where the look drifts and where dark mode breaks.\n\n---\n\n## 1. How to consume the theme\n\n- **Colors:** `sx={{ color: 'text.secondary', bgcolor: 'background.paper', borderColor: 'divider' }}` â€” MUI resolves dotted palette paths automatically in `sx`. In `styled`/JS use the callback form: `styled(Box)(({ theme }) => ({ color: theme.palette.text.secondary }))`.\n- **Spacing:** use the 8px unit via the spacing scale â€” `sx={{ p: 2, gap: 1, mt: 1.5 }}` (`2` = 16px, `1` = 8px). Don't write `padding: '16px'`.\n- **Radius:** `borderRadius: 1` (= `theme.shape.borderRadius` = 8) and multiples; for the fixed non-8 radii see Â§4.\n- **Typography:** prefer `Typography variant=...` and `theme.typography.*` over ad-hoc `fontSize`.\n- **Custom tokens:** roles the default MUI palette doesn't cover (column/track surfaces, the strong/hover border steps, `text-3/4`, section-header color, `primary-bg` tint, status colors) must exist in the theme under a namespace (e.g. `theme.palette.custom.*`) with light + dark values. Consume them the same way â€” `bgcolor: 'custom.column'`. **Never inline their hex.** If a needed token doesn't exist yet, add it to the theme, don't hardcode it in the component.\n\n---\n\n## 2. Role â†’ theme slot\n\nPick the slot by the element's **role**, not by how it looks in one mode:\n\n| Role | Theme slot |\n|---|---|\n| App background; tinted footer/action bars | `background.default` |\n| Column & sidebar surface | `custom.column` |\n| Segmented-control / toolbar track, hover fill | `custom.track` |\n| Card, dialog, popup, input surface | `background.paper` |\n| Hairlines, resting borders | `divider` |\n| Input borders, vertical separators | `custom.borderStrong` |\n| Border on hover | `custom.borderHover` |\n| Titles, values, headings | `text.primary` |\n| Body copy, field labels | `text.secondary` |\n| Meta, captions, resting icons | `custom.text3` |\n| Muted / placeholder / disabled | `custom.text4` |\n| Uppercase section/column headers | `custom.colHead` |\n| The one CTA, selection, focus, links, icon-hover | `primary.main` |\n| Contained-button hover | `primary.dark` |\n| Selected/tinted bg, focus ring, ID-chip bg | `custom.primaryBg` |\n| Text/icon on a primary fill | `primary.contrastText` |\n| Active / saved / online dot | `success.main` |\n| Destructive action | `error.main` |\n| Status swatch dots & ID-chip tints (decorative only) | `custom.status.*` |\n\nRules: **one** `primary` per surface (the CTA/selection accent) â€” everything else is `text-*`/`divider`. Status colors are **decoration only** (dots, chip tints), never interactive color. Dark-mode brightness/tinting is handled inside the theme's two palettes, so a correctly-sloted component needs zero per-mode code.\n\n---\n\n## 3. Layout\n\n- **Full-height app:** column flex â€” menu row / ribbon / content (`flex: 1; minHeight: 0`) / status bar. Fixed bands `flexShrink: 0`.\n- **Board:** horizontal-scroll flex row, `gap: 2` (16px), page padding `p: 2.5` (20px); columns `width: 296, flexShrink: 0`, internal column flex `gap: 1`.\n- **List view:** two-pane flex row filling the space between ribbon and status bar â€” sidebar `width: 280, flexShrink: 0`, editor pane `flex: 1, minWidth: 0` (the `minWidth: 0` is required so long content ellipsizes instead of blowing out the row).\n- **Panels (sidebar, editor card, dialogs):** column flex with stacked bands (header / [toolbar] / body / footer). The **body scrolls** (`overflow-y: auto; minHeight: 0`); header and footer are `flexShrink: 0` and never scroll away.\n- **Spacer pattern:** push trailing items with `<Box sx={{ flex: 1 }} />` rather than `margin-left: auto` sprinkled around, so rows stay predictable.\n- Use flex `gap` for spacing between siblings â€” don't hand-space with per-child margins.\n\n---\n\n## 4. Spacing, margin & size conventions\n\n- **4/8px grid, via `theme.spacing`.** page padding `2.5`; between columns `2`; inside columns / between related controls `1`; dialog body gap `2â€“2.25`; field labelâ†’control gap `~0.9` (7px).\n- **Margins:** prefer padding on containers + flex `gap` over element margins. Where a floating panel needs breathing room (e.g. editor card, toolbar inside a panel), use container padding (`p: 2 / 2.5`), not margins on the children.\n- **Fixed heights (px):** menu row 44, ribbon 52, status bar 32, section header 40, tab row 40, standard button / control 34, dense icon button 26â€“28, input 42.\n- **Fixed widths (px):** column 296, sidebar 280, search 260, standard dialog 480, wide/editor dialog 760.\n- **Radius family (px):** buttons/icon-buttons 8 (small 6â€“7), inputs 9, cards 10, columns/panels 12, dialogs/popups 14, chips/pills 99, color swatches 3. `borderRadius: 1` covers the 8 case; use explicit `'9px'` etc. for the others.\n\n---\n\n## 5. Borders & elevation\n\n- **Rest = border, not shadow.** Resting surfaces: `border: '1px solid'`, `borderColor: 'divider'`. Inputs use `custom.borderStrong`. **Shadow only when floating or lifted** (hover, drag, dialogs/popovers).\n- **Separation between bands:** a single 1px `divider` hairline. Don't stack a heavy rule *and* an outline â€” one line, let background contrast do the rest. Vertical separators inside toolbars: a 20px-tall `custom.borderStrong` rule.\n- **Elevation ladder (only where floating):** card hover `0 4px 12px rgba(16,24,40,0.12)`; dragging MUI `elevation 8` + `rotate(2deg)`; contained button `0 1px 2px rgba(16,24,40,0.15)`; dialog/popup `0 24px 60px rgba(16,24,40,0.28)`; scrim `rgba(16,24,40,0.45)` + `backdropFilter: blur(2px)`.\n- Set `MuiPaper.elevation: 0` and `MuiButton.disableElevation` globally in the theme; add the shadows above explicitly where the ladder calls for it.\n- **On dark backgrounds shadows read as nothing** â€” the theme already handles this by making hover raise `borderColor` (`custom.borderHover`) instead of relying on shadow.\n\n---\n\n## 6. Typography usage\n\nDrive everything from theme variants / `theme.typography`; avoid ad-hoc `fontSize`.\n\n- Titles/values/headings â†’ `text.primary`; body & labels â†’ `text.secondary`; meta â†’ `custom.text3`.\n- **Field labels:** a plain `Typography` (12px/600, `text.secondary`) placed **above** the control â€” **never** MUI floating/outlined `TextField` labels (they clash with the app's flat-label style).\n- **Section/column headers:** `Typography variant=\"overline\"` (uppercase, `letterSpacing ~0.7px`, `fontWeight 700`, `custom.colHead`).\n- **ID chips only** use monospace; everything else is the theme's default family.\n- `button.textTransform: 'none'` and `button.fontWeight: 600` are set in the theme â€” don't re-uppercase buttons.\n\n---\n\n## 7. Interaction states\n\nConsistent across all components; all colors from the theme:\n\n- **Ghost icon button** (`IconButton`): transparent â†’ hover `bgcolor: track` (or `background.paper` on a colored panel) + `color: primary.main`. Override MUI's default circular hover tint via `sx`.\n- **Outlined button:** `divider` border, `text.secondary` â†’ hover `borderColor/color: primary.main`. Destructive: hover `borderColor: error.main` + `bgcolor: custom.dangerBg`.\n- **Contained (primary) CTA:** `primary.main` + small shadow â†’ hover `primary.dark`.\n- **Input/field focus:** `borderColor: primary.main` + `boxShadow: 0 0 0 3px` in `custom.primaryBg` (the soft halo). Unfocused hover: `borderColor: custom.borderHover`.\n- **List/tree row:** hover `bgcolor: track`; selected `bgcolor: custom.primaryBg` + title `text.primary`.\n- **Row-level actions** (delete, â‹®): hidden at rest, shown on `:hover`/`:focus-within` via **opacity** (keep in DOM so width doesn't jump).\n- **Active tab/menu item:** 2px `primary.main` bottom border + `primary.main` text.\n- Every icon-only control gets a `Tooltip` (theme sets `arrow: true`) **and** an `aria-label`.\n\n---\n\n## 8. Component conventions (MUI primitives)\n\n- **Buttons:** `Button variant=\"contained\"` = the single CTA per surface; `variant=\"outlined\"` = secondary; `variant=\"text\"` = tertiary. Icon-only â†’ `IconButton` in a `Tooltip`. Don't use `Link` or text `Button` where an action button belongs (that reproduces the old text-link look).\n- **Icons:** `@mui/icons-material` **Outlined** variants; `fontSize: 18` in 34px buttons, `16` in dense, `13â€“15` inline. Don't hand-draw SVG.\n- **ID chip:** monospace, accent text on `custom.primaryBg`/status tint, `radius 5, flexShrink: 0`.\n- **Count chip:** `background.paper` bg, 1px `divider`, radius 9â€“10, `custom.text3`.\n- **State dot:** 7â€“8px circle + `text-3` label; green (`success.main`) = active/saved/online.\n- **Search:** pill `TextField` (`borderRadius: 99`, `bgcolor: background.default`), search start-adornment, `âŒ˜K` keycap end-adornment.\n- **Select:** `size=\"small\"`, optional dot+name via `renderValue`; 42px / radius-9 frame. When a select has a tooltip, keep the tooltip available while the select is closed and explicitly hide it for the entire time the select menu is open so it cannot cover the first option.\n- **Segmented control** (view switch, formatting toolbar): `ToggleButtonGroup` on a `custom.track` background; selected segment `background.paper` + `0 1px 2px` shadow + `primary` text.\n- **Dialog / popup:** `Dialog`/`Popover` with `PaperProps` â†’ `background.paper`, 1px `divider`, radius 14, big shadow; scrim via `slotProps.backdrop` (blur + tint). Bands separated by hairlines; footer on a `background.default` bar with top hairline; actions right-aligned (outlined Cancel + contained CTA). `autoFocus` first field; submit on `Enter` (`âŒ˜/Ctrl+Enter` in a textarea); close on `Esc`/backdrop.\n- **Empty state:** dashed target â€” `1.5px dashed custom.borderStrong`, radius 10, centered icon + `custom.text4` label. No \"click to add\" placeholder blocks.\n\n---\n\n## 9. Definition of done for a new component\n\n1. Zero hardcoded hex / raw px colors â€” every value comes from `theme.palette` / `theme.shape` / `theme.spacing` / `theme.typography`.\n2. Correct roleâ†’slot mapping (Â§2); at most one `primary` CTA on the surface.\n3. Borders at rest, shadow only when floating (Â§5); bands split by a single hairline.\n4. Hover **and** focus states on every interactive element (Â§7); icon buttons have tooltip + `aria-label`.\n5. Body scrolls, header/footer pinned; `minWidth: 0` on flex children that hold long text.\n6. Toggle to dark mode and confirm nothing breaks â€” if it does, you hardcoded a color somewhere (Â§1).\n\nComponent-specific detail lives in `GUIDANCE.md` (theme definition + board/list/dialog), `CARD_POPUP_GUIDE.md`, `RUN_DIALOG_GUIDE.md`, and `SIDEBAR_ACTIONS_GUIDE.md`.\n\r\n",
design\releases\0_2_0\card__1ebcfe45-9445-47e6-8619-6c72708bd91b.json:206:          "output": "import { Box, Typography } from '@mui/material'\nimport {\n    useEffect, useRef, useState, useSyncExternalStore, type KeyboardEvent, type PointerEvent as ReactPointerEvent, type ReactNode,\n} from 'react'\nimport { ACTION_PROMPT_PLACEHOLDERS } from '../../../data/action_placeholders'\nimport { dialogService } from '../../../services/dialog_service'\nimport type { ActionPromptDraft } from '../../../services/actions/action_prompt_draft_service'\nimport { MarkdownEditor, type MarkdownEditorHandle } from '../../editor/markdown_editor'\n\nconst MIN_PROMPT_HEIGHT = 72\nconst MIN_CHAT_HEIGHT = 96\nconst DEFAULT_PROMPT_HEIGHT = 140\nconst PROMPT_RESIZE_STEP = 24\nconst PROMPT_HEIGHT_STORAGE_KEY = 'md2.actionPromptHeight'\n\nfunction readStoredPromptHeight(): number {\n    const storedValue = window.localStorage.getItem(PROMPT_HEIGHT_STORAGE_KEY)\n    const parsedValue = storedValue ? Number.parseInt(storedValue, 10) : Number.NaN\n\n    return Number.isNaN(parsedValue) ? DEFAULT_PROMPT_HEIGHT : parsedValue\n}\n\ninterface ActionAgentPromptProps {\n    convertMessage: string | null\n    disabled: boolean\n    onRunShortcut?: () => void\n    promptDraft: ActionPromptDraft\n    responsePrompts?: ReactNode\n}\n\n/** Resizable prompt editor shown below an agent conversation. */\nexport function ActionAgentPrompt(props: ActionAgentPromptProps) {\n    const {convertMessage, disabled, onRunShortcut, promptDraft, responsePrompts} = props\n    const promptEditorRef = useRef<MarkdownEditorHandle>(null)\n    const promptHeightStartRef = useRef(0)\n    const pointerStartYRef = useRef(0)\n    const splitContainerRef = useRef<HTMLElement | null>(null)\n    const [promptHeight, setPromptHeight] = useState(readStoredPromptHeight)\n    const [resizingPrompt, setResizingPrompt] = useState(false)\n    const editorSnapshot = useSyncExternalStore(\n        promptDraft.subscribeEditor,\n        promptDraft.getEditorSnapshot,\n        promptDraft.getEditorSnapshot,\n    )\n\n    useEffect(() => {\n        promptEditorRef.current?.setMarkdown(promptDraft.getSnapshot())\n    }, [editorSnapshot.replacementRevision, promptDraft])\n\n    const handlePromptChange = (value: string) => {\n        promptDraft.edit(value)\n        void promptDraft.synchronize().catch((error: unknown) => {\n            dialogService.error(error, { fallbackMessage: 'Could not queue agent prompt' })\n        })\n    }\n\n    const clampPromptHeight = (proposed: number) => {\n        const container = splitContainerRef.current\n        const available = container ? container.getBoundingClientRect().height - MIN_CHAT_HEIGHT : proposed\n        const max = Math.max(MIN_PROMPT_HEIGHT, available)\n\n        return Math.min(Math.max(proposed, MIN_PROMPT_HEIGHT), max)\n    }\n\n    const persistPromptHeight = (height: number) => {\n        window.localStorage.setItem(PROMPT_HEIGHT_STORAGE_KEY, String(Math.round(height)))\n    }\n\n    const handleSplitPointerDown = (event: ReactPointerEvent<HTMLDivElement>) => {\n        event.preventDefault()\n        splitContainerRef.current = event.currentTarget.parentElement\n        promptHeightStartRef.current = promptHeight\n        pointerStartYRef.current = event.clientY\n        setResizingPrompt(true)\n        event.currentTarget.setPointerCapture?.(event.pointerId)\n    }\n\n    const handleSplitPointerMove = (event: ReactPointerEvent<HTMLDivElement>) => {\n        if (!resizingPrompt) return\n\n        const delta = pointerStartYRef.current - event.clientY\n        setPromptHeight(clampPromptHeight(promptHeightStartRef.current + delta))\n    }\n\n    const handleSplitPointerUp = (event: ReactPointerEvent<HTMLDivElement>) => {\n        if (!resizingPrompt) return\n\n        setResizingPrompt(false)\n        event.currentTarget.releasePointerCapture?.(event.pointerId)\n        setPromptHeight((height) => {\n            persistPromptHeight(height)\n\n            return height\n        })\n    }\n\n    const handleSplitKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {\n        splitContainerRef.current = event.currentTarget.parentElement\n        const nextByKey: Record<string, number> = {\n            ArrowDown: promptHeight - PROMPT_RESIZE_STEP,\n            ArrowUp: promptHeight + PROMPT_RESIZE_STEP,\n        }\n        const next = nextByKey[event.key]\n        if (next === undefined) return\n\n        event.preventDefault()\n        const clamped = clampPromptHeight(next)\n        setPromptHeight(clamped)\n        persistPromptHeight(clamped)\n    }\n\n    const handlePromptKeyDownCapture = (event: KeyboardEvent<HTMLDivElement>) => {\n        if (event.key !== 'Enter' || (!event.ctrlKey && !event.metaKey) || !onRunShortcut) return\n\n        event.preventDefault()\n        event.stopPropagation()\n        promptEditorRef.current?.flush()\n        onRunShortcut()\n    }\n\n    return (\n        <>\n            <Box\n                aria-label=\"Resize prompt\"\n                aria-orientation=\"horizontal\"\n                aria-valuemin={MIN_PROMPT_HEIGHT}\n                aria-valuenow={Math.round(promptHeight)}\n                onKeyDown={handleSplitKeyDown}\n                onPointerDown={handleSplitPointerDown}\n                onPointerMove={handleSplitPointerMove}\n                onPointerUp={handleSplitPointerUp}\n                role=\"separator\"\n                sx={{\n                    bgcolor: resizingPrompt ? 'primary.main' : 'divider',\n                    borderRadius: '2px',\n                    cursor: 'row-resize',\n                    flexShrink: 0,\n                    height: '3px',\n                    mx: 'auto',\n                    my: '2px',\n                    width: '100%',\n                    '&:hover': { bgcolor: 'primary.main' },\n                }}\n                tabIndex={0}\n            />\n            <Box\n                aria-label=\"Prompt\"\n                onKeyDownCapture={handlePromptKeyDownCapture}\n                sx={{\n                    borderRadius: '9px',\n                    border: 1,\n                    borderColor: 'custom.borderStrong',\n                    display: 'flex',\n                    flexDirection: 'column',\n                    flexShrink: 0,\n                    height: promptHeight,\n                    overflow: 'hidden',\n                    '&:focus-within': {\n                        borderColor: 'primary.main',\n                        boxShadow: (theme) => `0 0 0 3px ${theme.palette.action.selected}`,\n                    },\n                }}\n            >\n                <Box sx={{ flex: 1, minHeight: 0, overflowY: 'auto', px: 1 }}>\n                    <MarkdownEditor\n                        flushOnBlur\n                        hideToolbar\n                        markdown={promptDraft.getSnapshot()}\n                        onChange={handlePromptChange}\n                        onLiveChange={promptDraft.edit}\n                        placeholders={ACTION_PROMPT_PLACEHOLDERS}\n                        readOnly={disabled || editorSnapshot.preparationStatus !== 'ready'}\n                        ref={promptEditorRef}\n                    />\n                </Box>\n                {responsePrompts}\n            </Box>\n            {convertMessage ? (\n                <Typography color=\"text.secondary\" role=\"status\" variant=\"caption\">\n                    {convertMessage}\n                </Typography>\n            ) : null}\n        </>\n    )\n}\n\r\nimport { act, cleanup, fireEvent, render, screen } from '@testing-library/react'\nimport { afterEach, describe, expect, it, vi } from 'vitest'\nimport { ActionAgentPrompt } from './action_agent_prompt'\nimport { ACTION_PROMPT_PLACEHOLDERS } from '../../../data/action_placeholders'\nimport { ActionPromptDraft } from '../../../services/actions/action_prompt_draft_service'\n\nconst setMarkdown = vi.hoisted(() => vi.fn())\n\nvi.mock('../../editor/markdown_editor', async () => {\n    const { forwardRef, useImperativeHandle, useRef, useState } = await import('react')\n\n    return {\n        MarkdownEditor: forwardRef(function MarkdownEditorMock(props: {\n            flushOnBlur?: boolean\n            markdown: string\n            onChange: (markdown: string) => void\n            onLiveChange?: (markdown: string) => void\n            placeholders?: readonly { name: string }[]\n            readOnly?: boolean\n        }, ref) {\n            const valueRef = useRef(props.markdown)\n            const [value, setValue] = useState(props.markdown)\n            useImperativeHandle(ref, () => ({\n                flush: () => {\n                    props.onChange(valueRef.current)\n\n                    return true\n                },\n                getMarkdown: () => valueRef.current,\n                setMarkdown: (markdown: string) => {\n                    valueRef.current = markdown\n                    setValue(markdown)\n                    setMarkdown(markdown)\n                },\n            }))\n\n            return (\n                <textarea\n                    aria-label=\"Markdown prompt\"\n                    data-flush-on-blur={props.flushOnBlur ? 'true' : 'false'}\n                    data-placeholders={props.placeholders?.map(({ name }) => name).join(',')}\n                    value={value}\n                    onBlur={(event) => props.onChange(event.currentTarget.value)}\n                    onChange={(event) => {\n                        valueRef.current = event.currentTarget.value\n                        setValue(event.currentTarget.value)\n                        props.onLiveChange?.(event.currentTarget.value)\n                    }}\n                    onKeyDown={(event) => {\n                        if (event.key !== 'Enter') return\n\n                        const nextValue = `${valueRef.current}\\n`\n                        valueRef.current = nextValue\n                        setValue(nextValue)\n                        props.onLiveChange?.(nextValue)\n                    }}\n                    readOnly={props.readOnly}\n                />\n            )\n        }),\n    }\n})\n\nafterEach(cleanup)\n\ndescribe('ActionAgentPrompt', () => {\n    it('configures action placeholders on its hidden-toolbar editor', () => {\n        const promptDraft = new ActionPromptDraft('', false, null)\n        render(\n            <ActionAgentPrompt\n                convertMessage={null}\n                disabled={false}\n                promptDraft={promptDraft}\n            />,\n        )\n\n        expect(screen.getByLabelText('Markdown prompt')).toHaveAttribute(\n            'data-placeholders',\n            ACTION_PROMPT_PLACEHOLDERS.map(({ name }) => name).join(','),\n        )\n        expect(screen.getByLabelText('Markdown prompt').getAttribute('data-placeholders')).toContain('this-card')\n    })\n\n    it('keeps typing local and synchronizes the prompt on blur', () => {\n        const promptDraft = new ActionPromptDraft('', false, null)\n        const synchronize = vi.spyOn(promptDraft, 'synchronize')\n        render(\n            <ActionAgentPrompt\n                convertMessage={null}\n                disabled={false}\n                promptDraft={promptDraft}\n            />,\n        )\n        const prompt = screen.getByLabelText('Markdown prompt')\n\n        fireEvent.change(prompt, { target: { value: 'Draft' } })\n\n        expect(synchronize).not.toHaveBeenCalled()\n        expect(promptDraft.getSnapshot()).toBe('Draft')\n        expect(prompt).toHaveAttribute('data-flush-on-blur', 'true')\n\n        fireEvent.blur(prompt)\n\n        expect(synchronize).toHaveBeenCalledOnce()\n    })\n\n    it.each([\n        { keyModifier: { ctrlKey: true }, shortcut: 'Ctrl+Enter' },\n        { keyModifier: { metaKey: true }, shortcut: 'Meta+Enter' },\n    ])('flushes the latest prompt before running $shortcut without passing it to the editor', ({ keyModifier }) => {\n        const handleRunShortcut = vi.fn()\n        const promptDraft = new ActionPromptDraft('', false, null)\n        const synchronize = vi.spyOn(promptDraft, 'synchronize')\n        render(\n            <ActionAgentPrompt\n                convertMessage={null}\n                disabled={false}\n                onRunShortcut={handleRunShortcut}\n                promptDraft={promptDraft}\n            />,\n        )\n        const prompt = screen.getByLabelText('Markdown prompt')\n\n        fireEvent.change(prompt, { target: { value: 'Run this' } })\n        fireEvent.keyDown(prompt, { ...keyModifier, key: 'Enter' })\n\n        expect(synchronize).toHaveBeenCalledOnce()\n        expect(synchronize.mock.invocationCallOrder[0]).toBeLessThan(handleRunShortcut.mock.invocationCallOrder[0])\n        expect(handleRunShortcut).toHaveBeenCalledOnce()\n        expect(promptDraft.getSnapshot()).toBe('Run this')\n        expect(prompt).toHaveValue('Run this')\n    })\n\n    it('keeps plain Enter and Shift+Enter editor behavior', () => {\n        const promptDraft = new ActionPromptDraft('Line', false, null)\n        render(\n            <ActionAgentPrompt\n                convertMessage={null}\n                disabled={false}\n                onRunShortcut={vi.fn()}\n                promptDraft={promptDraft}\n            />,\n        )\n        const prompt = screen.getByLabelText('Markdown prompt')\n\n        fireEvent.keyDown(prompt, { key: 'Enter' })\n        fireEvent.keyDown(prompt, { key: 'Enter', shiftKey: true })\n\n        expect(promptDraft.getSnapshot()).toBe('Line\\n\\n')\n        expect(prompt).toHaveValue('Line\\n\\n')\n    })\n\n    it('keeps Ctrl+Enter editor behavior when no shortcut callback exists', () => {\n        const promptDraft = new ActionPromptDraft('Line', false, null)\n        render(\n            <ActionAgentPrompt\n                convertMessage={null}\n                disabled={false}\n                promptDraft={promptDraft}\n            />,\n        )\n        const prompt = screen.getByLabelText('Markdown prompt')\n\n        fireEvent.keyDown(prompt, { ctrlKey: true, key: 'Enter' })\n\n        expect(promptDraft.getSnapshot()).toBe('Line\\n')\n        expect(prompt).toHaveValue('Line\\n')\n    })\n\n    it('applies each external replacement to the mounted editor once', () => {\n        const promptDraft = new ActionPromptDraft('Initial', false, null)\n        render(\n            <ActionAgentPrompt\n                convertMessage={null}\n                disabled={false}\n                promptDraft={promptDraft}\n            />,\n        )\n        setMarkdown.mockClear()\n\n        act(() => promptDraft.replace('Prepared'))\n\n        expect(setMarkdown).toHaveBeenCalledOnce()\n        expect(setMarkdown).toHaveBeenCalledWith('Prepared')\n        expect(screen.getByLabelText('Markdown prompt')).toHaveValue('Prepared')\n    })\n})\n\r\n---\ninternalId: f2ec9e28-8064-4707-bce9-b62f24d57524\n---\n\n# App Style Guide â€” Kanban / MDÂ² (React + MUI)\n\nHow to build **any new component** so it matches the app. This is written for **Material UI v5+** components.\n\n**The theme is the source of truth.** All color, radius, base typography, and spacing units live in the single `createTheme` (defined in `GUIDANCE.md` Â§1/Â§9). This guide does **not** define colors â€” it tells you **which theme value to use for which role**, and covers the things the theme can't encode: layout, spacing/margins, borders, elevation, and component conventions.\n\n**The one rule that matters:** never write a raw hex, px radius, or magic color into a component. Read it from the theme (`theme.palette.*`, `theme.shape`, `theme.typography`, `theme.spacing`). If a component has a hardcoded hex in its `sx`/styled, it's wrong â€” that's exactly where the look drifts and where dark mode breaks.\n\n---\n\n## 1. How to consume the theme\n\n- **Colors:** `sx={{ color: 'text.secondary', bgcolor: 'background.paper', borderColor: 'divider' }}` â€” MUI resolves dotted palette paths automatically in `sx`. In `styled`/JS use the callback form: `styled(Box)(({ theme }) => ({ color: theme.palette.text.secondary }))`.\n- **Spacing:** use the 8px unit via the spacing scale â€” `sx={{ p: 2, gap: 1, mt: 1.5 }}` (`2` = 16px, `1` = 8px). Don't write `padding: '16px'`.\n- **Radius:** `borderRadius: 1` (= `theme.shape.borderRadius` = 8) and multiples; for the fixed non-8 radii see Â§4.\n- **Typography:** prefer `Typography variant=...` and `theme.typography.*` over ad-hoc `fontSize`.\n- **Custom tokens:** roles the default MUI palette doesn't cover (column/track surfaces, the strong/hover border steps, `text-3/4`, section-header color, `primary-bg` tint, status colors) must exist in the theme under a namespace (e.g. `theme.palette.custom.*`) with light + dark values. Consume them the same way â€” `bgcolor: 'custom.column'`. **Never inline their hex.** If a needed token doesn't exist yet, add it to the theme, don't hardcode it in the component.\n\n---\n\n## 2. Role â†’ theme slot\n\nPick the slot by the element's **role**, not by how it looks in one mode:\n\n| Role | Theme slot |\n|---|---|\n| App background; tinted footer/action bars | `background.default` |\n| Column & sidebar surface | `custom.column` |\n| Segmented-control / toolbar track, hover fill | `custom.track` |\n| Card, dialog, popup, input surface | `background.paper` |\n| Hairlines, resting borders | `divider` |\n| Input borders, vertical separators | `custom.borderStrong` |\n| Border on hover | `custom.borderHover` |\n| Titles, values, headings | `text.primary` |\n| Body copy, field labels | `text.secondary` |\n| Meta, captions, resting icons | `custom.text3` |\n| Muted / placeholder / disabled | `custom.text4` |\n| Uppercase section/column headers | `custom.colHead` |\n| The one CTA, selection, focus, links, icon-hover | `primary.main` |\n| Contained-button hover | `primary.dark` |\n| Selected/tinted bg, focus ring, ID-chip bg | `custom.primaryBg` |\n| Text/icon on a primary fill | `primary.contrastText` |\n| Active / saved / online dot | `success.main` |\n| Destructive action | `error.main` |\n| Status swatch dots & ID-chip tints (decorative only) | `custom.status.*` |\n\nRules: **one** `primary` per surface (the CTA/selection accent) â€” everything else is `text-*`/`divider`. Status colors are **decoration only** (dots, chip tints), never interactive color. Dark-mode brightness/tinting is handled inside the theme's two palettes, so a correctly-sloted component needs zero per-mode code.\n\n---\n\n## 3. Layout\n\n- **Full-height app:** column flex â€” menu row / ribbon / content (`flex: 1; minHeight: 0`) / status bar. Fixed bands `flexShrink: 0`.\n- **Board:** horizontal-scroll flex row, `gap: 2` (16px), page padding `p: 2.5` (20px); columns `width: 296, flexShrink: 0`, internal column flex `gap: 1`.\n- **List view:** two-pane flex row filling the space between ribbon and status bar â€” sidebar `width: 280, flexShrink: 0`, editor pane `flex: 1, minWidth: 0` (the `minWidth: 0` is required so long content ellipsizes instead of blowing out the row).\n- **Panels (sidebar, editor card, dialogs):** column flex with stacked bands (header / [toolbar] / body / footer). The **body scrolls** (`overflow-y: auto; minHeight: 0`); header and footer are `flexShrink: 0` and never scroll away.\n- **Spacer pattern:** push trailing items with `<Box sx={{ flex: 1 }} />` rather than `margin-left: auto` sprinkled around, so rows stay predictable.\n- Use flex `gap` for spacing between siblings â€” don't hand-space with per-child margins.\n\n---\n\n## 4. Spacing, margin & size conventions\n\n- **4/8px grid, via `theme.spacing`.** page padding `2.5`; between columns `2`; inside columns / between related controls `1`; dialog body gap `2â€“2.25`; field labelâ†’control gap `~0.9` (7px).\n- **Margins:** prefer padding on containers + flex `gap` over element margins. Where a floating panel needs breathing room (e.g. editor card, toolbar inside a panel), use container padding (`p: 2 / 2.5`), not margins on the children.\n- **Fixed heights (px):** menu row 44, ribbon 52, status bar 32, section header 40, tab row 40, standard button / control 34, dense icon button 26â€“28, input 42.\n- **Fixed widths (px):** column 296, sidebar 280, search 260, standard dialog 480, wide/editor dialog 760.\n- **Radius family (px):** buttons/icon-buttons 8 (small 6â€“7), inputs 9, cards 10, columns/panels 12, dialogs/popups 14, chips/pills 99, color swatches 3. `borderRadius: 1` covers the 8 case; use explicit `'9px'` etc. for the others.\n\n---\n\n## 5. Borders & elevation\n\n- **Rest = border, not shadow.** Resting surfaces: `border: '1px solid'`, `borderColor: 'divider'`. Inputs use `custom.borderStrong`. **Shadow only when floating or lifted** (hover, drag, dialogs/popovers).\n- **Separation between bands:** a single 1px `divider` hairline. Don't stack a heavy rule *and* an outline â€” one line, let background contrast do the rest. Vertical separators inside toolbars: a 20px-tall `custom.borderStrong` rule.\n- **Elevation ladder (only where floating):** card hover `0 4px 12px rgba(16,24,40,0.12)`; dragging MUI `elevation 8` + `rotate(2deg)`; contained button `0 1px 2px rgba(16,24,40,0.15)`; dialog/popup `0 24px 60px rgba(16,24,40,0.28)`; scrim `rgba(16,24,40,0.45)` + `backdropFilter: blur(2px)`.\n- Set `MuiPaper.elevation: 0` and `MuiButton.disableElevation` globally in the theme; add the shadows above explicitly where the ladder calls for it.\n- **On dark backgrounds shadows read as nothing** â€” the theme already handles this by making hover raise `borderColor` (`custom.borderHover`) instead of relying on shadow.\n\n---\n\n## 6. Typography usage\n\nDrive everything from theme variants / `theme.typography`; avoid ad-hoc `fontSize`.\n\n- Titles/values/headings â†’ `text.primary`; body & labels â†’ `text.secondary`; meta â†’ `custom.text3`.\n- **Field labels:** a plain `Typography` (12px/600, `text.secondary`) placed **above** the control â€” **never** MUI floating/outlined `TextField` labels (they clash with the app's flat-label style).\n- **Section/column headers:** `Typography variant=\"overline\"` (uppercase, `letterSpacing ~0.7px`, `fontWeight 700`, `custom.colHead`).\n- **ID chips only** use monospace; everything else is the theme's default family.\n- `button.textTransform: 'none'` and `button.fontWeight: 600` are set in the theme â€” don't re-uppercase buttons.\n\n---\n\n## 7. Interaction states\n\nConsistent across all components; all colors from the theme:\n\n- **Ghost icon button** (`IconButton`): transparent â†’ hover `bgcolor: track` (or `background.paper` on a colored panel) + `color: primary.main`. Override MUI's default circular hover tint via `sx`.\n- **Outlined button:** `divider` border, `text.secondary` â†’ hover `borderColor/color: primary.main`. Destructive: hover `borderColor: error.main` + `bgcolor: custom.dangerBg`.\n- **Contained (primary) CTA:** `primary.main` + small shadow â†’ hover `primary.dark`.\n- **Input/field focus:** `borderColor: primary.main` + `boxShadow: 0 0 0 3px` in `custom.primaryBg` (the soft halo). Unfocused hover: `borderColor: custom.borderHover`.\n- **List/tree row:** hover `bgcolor: track`; selected `bgcolor: custom.primaryBg` + title `text.primary`.\n- **Row-level actions** (delete, â‹®): hidden at rest, shown on `:hover`/`:focus-within` via **opacity** (keep in DOM so width doesn't jump).\n- **Active tab/menu item:** 2px `primary.main` bottom border + `primary.main` text.\n- Every icon-only control gets a `Tooltip` (theme sets `arrow: true`) **and** an `aria-label`.\n\n---\n\n## 8. Component conventions (MUI primitives)\n\n- **Buttons:** `Button variant=\"contained\"` = the single CTA per surface; `variant=\"outlined\"` = secondary; `variant=\"text\"` = tertiary. Icon-only â†’ `IconButton` in a `Tooltip`. Don't use `Link` or text `Button` where an action button belongs (that reproduces the old text-link look).\n- **Icons:** `@mui/icons-material` **Outlined** variants; `fontSize: 18` in 34px buttons, `16` in dense, `13â€“15` inline. Don't hand-draw SVG.\n- **ID chip:** monospace, accent text on `custom.primaryBg`/status tint, `radius 5, flexShrink: 0`.\n- **Count chip:** `background.paper` bg, 1px `divider`, radius 9â€“10, `custom.text3`.\n- **State dot:** 7â€“8px circle + `text-3` label; green (`success.main`) = active/saved/online.\n- **Search:** pill `TextField` (`borderRadius: 99`, `bgcolor: background.default`), search start-adornment, `âŒ˜K` keycap end-adornment.\n- **Select:** `size=\"small\"`, optional dot+name via `renderValue`; 42px / radius-9 frame. When a select has a tooltip, keep the tooltip available while the select is closed and explicitly hide it for the entire time the select menu is open so it cannot cover the first option.\n- **Segmented control** (view switch, formatting toolbar): `ToggleButtonGroup` on a `custom.track` background; selected segment `background.paper` + `0 1px 2px` shadow + `primary` text.\n- **Dialog / popup:** `Dialog`/`Popover` with `PaperProps` â†’ `background.paper`, 1px `divider`, radius 14, big shadow; scrim via `slotProps.backdrop` (blur + tint). Bands separated by hairlines; footer on a `background.default` bar with top hairline; actions right-aligned (outlined Cancel + contained CTA). `autoFocus` first field; submit on `Enter` (`âŒ˜/Ctrl+Enter` in a textarea); close on `Esc`/backdrop.\n- **Empty state:** dashed target â€” `1.5px dashed custom.borderStrong`, radius 10, centered icon + `custom.text4` label. No \"click to add\" placeholder blocks.\n\n---\n\n## 9. Definition of done for a new component\n\n1. Zero hardcoded hex / raw px colors â€” every value comes from `theme.palette` / `theme.shape` / `theme.spacing` / `theme.typography`.\n2. Correct roleâ†’slot mapping (Â§2); at most one `primary` CTA on the surface.\n3. Borders at rest, shadow only when floating (Â§5); bands split by a single hairline.\n4. Hover **and** focus states on every interactive element (Â§7); icon buttons have tooltip + `aria-label`.\n5. Body scrolls, header/footer pinned; `minWidth: 0` on flex children that hold long text.\n6. Toggle to dark mode and confirm nothing breaks â€” if it does, you hardcoded a color somewhere (Â§1).\n\nComponent-specific detail lives in `GUIDANCE.md` (theme definition + board/list/dialog), `CARD_POPUP_GUIDE.md`, `RUN_DIALOG_GUIDE.md`, and `SIDEBAR_ACTIONS_GUIDE.md`.\n\r\n",
design\releases\0_2_0\card__1ebcfe45-9445-47e6-8619-6c72708bd91b.json:751:          "content": "design\\activity\\card__05d5d49c-401f-42cd-b3cc-074e169631dd.json:691:          \"content\": \".\\\\design\\\\releases\\\\0_1_0\\\\card__f9a450d8-0f93-4487-99f3-23dcc07b42b2.json:276:          \\\"content\\\": \\\"import { actionContextIdentity } from '../../data/action_context'\\\\nimport type { ActionContext } from '../../data/action_context'\\\\nimport type { ActionDefinition } from '../../data/action_types'\\\\nimport type { AgentConversation, AgentConversationEntry, AgentConversationEventEntry } from '../../data/data_types'\\\\nimport type {\\\\n    AgentApproval,\\\\n    AgentApprovalDecision,\\\\n    AgentApprovalRequestId,\\\\n    AgentQuestion,\\\\n    ActionRunEvent,\\\\n    ActionRunStatus,\\\\n    ActionRunTerminalStatus,\\\\n    ActionRunUpdate,\\\\n    ActionRunInput,\\\\n    ActionRunLogEntry,\\\\n    ActionRunResult,\\\\n} from '../../data/action_run_types'\\\\nimport { getElectronActionBridge } from '../../data/electron_action_bridge'\\\\nimport type { ElectronActionBridge } from '../../data/electron_action_bridge'\\\\nimport { actionService } from './action_service'\\\\nimport { actionPromptDraftService } from './action_prompt_draft_service'\\\\nimport { register } from '.././service_injector'\\\\n\\\\nconst TERMINAL_STATUSES = new Set<ActionRunTerminalStatus>(['cancelled', 'completed', 'failed', 'okButNotAfter'])\\\\nconst ACTIVE_STATUSES = new Set<ActionRunStatus>(['queued', 'running', 'waitingForInput'])\\\\nconst EMPTY_ACTIVE_RUNS: ActiveActionRun[] = []\\\\n\\\\nexport interface ActionRun {\\\\n    activeActionAutoFinish: ActionDefinition['autoFinish']\\\\n    activeActionId: string | null\\\\n    activeActionStreaming: boolean\\\\n    activeActionType: ActionDefinition['type'] | null\\\\n    conversation: AgentConversation | null\\\\n    context: ActionContext\\\\n    runId: string\\\\n    logs: ActionRunLogEntry[]\\\\n    approvals: LiveAgentApproval[]\\\\n    interactionReady: boolean\\\\n    question: LiveAgentQuestion | null\\\\n    reference: string | null\\\\n    rootActionId: string\\\\n    status: ActionRunStatus\\\\n}\\\\n\\\\nexport interface LiveAgentApproval extends AgentApproval {\\\\n    submitted: boolean\\\\n}\\\\n\\\\nexport interface LiveAgentQuestion {\\\\n    questions: AgentQuestion[]\\\\n    requestId: number | string | null\\\\n}\\\\n\\\\nexport interface ActiveActionRun {\\\\n    rootActionId: string\\\\n    runId: string\\\\n    status: ActionRunStatus\\\\n}\\\\n\\\\ntype EventListener = (event: ActionRunEvent) => void\\\\ntype StoreListener = () => void\\\\n\\\\nfunction actionName(actionId: string) {\\\\n    return actionService.getActions().find((action) => action.id === actionId)?.label ?? actionId\\\\n}\\\\n\\\\nfunction actionType(actionId: string) {\\\\n    return actionService.getActions().find((action) => action.id === actionId)?.type ?? null\\\\n}\\\\n\\\\nfunction actionStreaming(actionId: string) {\\\\n    return actionService.getActions().find((action) => action.id === actionId)?.streaming ?? false\\\\n}\\\\n\\\\nfunction createLog(event: ActionRunEvent): ActionRunLogEntry {\\\\n    return {\\\\n        ...(event.type === 'action' && event.accessLevel ? { accessLevel: event.accessLevel } : {}),\\\\n        actionId: event.actionId,\\\\n        actionName: actionName(event.actionId),\\\\n        ...(event.type === 'action' && event.approvalPolicy ? { approvalPolicy: event.approvalPolicy } : {}),\\\\n        command: event.type === 'action' ? event.command ?? null : null,\\\\n        message: event.type === 'action' ? event.message ?? `${actionName(event.actionId)} ${event.status}` : `${actionName(event.actionId)} running`,\\\\n        phase: event.phase,\\\\n        status: event.status,\\\\n        stderr: '',\\\\n        stdout: '',\\\\n        ...(event.type === 'action' && event.thinkingLevel ? { thinkingLevel: event.thinkingLevel } : {}),\\\\n    }\\\\n}\\\\n\\\\nfunction runningLogIndex(logs: ActionRunLogEntry[], event: ActionRunEvent) {\\\\n    return logs.findLastIndex((log) => (\\\\n        log.actionId === event.actionId\\\\n        && log.phase === event.phase\\\\n        && (log.status === 'queued' || log.status === 'running')\\\\n    ))\\\\n}\\\\n\\\\ntype AgentOutputUpdate = Pick<\\\\n    Extract<ActionRunUpdate, { kind: 'error' | 'output' }>,\\\\n    'content' | 'previousContent' | 'replace'\\\\n>\\\\n\\\\nfunction updatedStdout(currentStdout: string, update: AgentOutputUpdate) {\\\\n    if (!update.replace) return `${currentStdout}${update.content}`\\\\n    if (update.previousContent === undefined) throw new Error('Missing previous assistant output')\\\\n    if (!currentStdout.endsWith(update.previousContent)) throw new Error('Assistant output replacement is out of order')\\\\n\\\\n    return `${currentStdout.slice(0, currentStdout.length - update.previousContent.length)}${update.content}`\\\\n}\\\\n\\\\nfunction updateActionLogs(logs: ActionRunLogEntry[], event: Extract<ActionRunEvent, { type: 'action' }>) {\\\\n    const currentIndex = runningLogIndex(logs, event)\\\\n    if (currentIndex < 0) return [...logs, createLog(event)]\\\\n    const current = logs[currentIndex]\\\\n    const next = [...logs]\\\\n    next[currentIndex] = {\\\\n        ...current,\\\\n        ...(event.accessLevel ? { accessLevel: event.accessLevel } : {}),\\\\n        ...(event.approvalPolicy ? { approvalPolicy: event.approvalPolicy } : {}),\\\\n        command: event.command ?? current.command,\\\\n        message: event.message ?? `${actionName(event.actionId)} ${event.status}`,\\\\n        status: event.status,\\\\n        ...(event.thinkingLevel ? { thinkingLevel: event.thinkingLevel } : {}),\\\\n    }\\\\n\\\\n    return next\\\\n}\\\\n\\\\nfunction updateOutputLogs(\\\\n    logs: ActionRunLogEntry[],\\\\n    event: Extract<ActionRunEvent, { type: 'update' }>,\\\\n    update: Extract<ActionRunUpdate, { kind: 'error' | 'output' }>,\\\\n) {\\\\n    const currentIndex = logs.findLastIndex((log) => (\\\\n        log.actionId === event.actionId && log.phase === event.phase && log.status === 'running'\\\\n    ))\\\\n    const current = currentIndex >= 0 ? logs[currentIndex] : createLog(event)\\\\n    const updated = {\\\\n        ...current,\\\\n        command: update.command ?? current.command,\\\\n        stderr: update.kind === 'error' ? `${current.stderr}${update.content}` : current.stderr,\\\\n        stdout: update.kind === 'output' ? updatedStdout(current.stdout, update) : current.stdout,\\\\n    }\\\\n    if (currentIndex < 0) return [...logs, updated]\\\\n    const next = [...logs]\\\\n    next[currentIndex] = updated\\\\n\\\\n    return next\\\\n}\\\\n\\\\nfunction eventIdentity(event: AgentConversationEventEntry) {\\\\n    return event.providerItemId ?? event.id\\\\n}\\\\n\\\\nfunction upsertAgentEvent(entries: AgentConversationEntry[], event: AgentConversationEventEntry) {\\\\n    const identity = eventIdentity(event)\\\\n    const currentIndex = entries.findIndex((entry) => entry.kind === 'event' && eventIdentity(entry) === identity)\\\\n    if (currentIndex < 0) return [...entries, event]\\\\n\\\\n    const current = entries[currentIndex]\\\\n    const next = [...entries]\\\\n    next[currentIndex] = {\\\\n        ...event,\\\\n        ...(event.sequence === undefined && current.sequence !== undefined ? { sequence: current.sequence } : {}),\\\\n    }\\\\n\\\\n    return next\\\\n}\\\\n\\\\nfunction nextConversationSequence(conversation: AgentConversation) {\\\\n    const sequences = conversation.entries.map(({ sequence }) => sequence)\\\\n        .filter((sequence): sequence is number => sequence !== undefined)\\\\n\\\\n    return sequences.length > 0 ? Math.max(...sequences) + 1 : undefined\\\\n}\\\\n\\\\nfunction appendAssistantMessage(\\\\n    conversation: AgentConversation,\\\\n    update: { content: string, messageId?: string, replace?: boolean, sequence?: number },\\\\n) {\\\\n    