    const dataBridge = {
        ...createBridge(DATA_METHODS),
        onMergeConflictSessionChanged: (callback) => subscribeBridge('onMergeConflictSessionChanged', [], callback),
        onWorktreesChanged: (callback) => subscribeBridge('onWorktreesChanged', [], callback),
